using System.Windows; using System.Windows.Controls; using AshkanIndustrialOperations.Services;
namespace AshkanIndustrialOperations.Views; public partial class TelemetryView:UserControl { readonly TelemetrySimulator _sim; public TelemetryView(TelemetrySimulator sim){InitializeComponent();_sim=sim;TelemetryGrid.ItemsSource=_sim.Samples;Update();} void Start_Click(object s,RoutedEventArgs e){_sim.Start();Update();} void Stop_Click(object s,RoutedEventArgs e){_sim.Stop();Update();} void Update(){StreamState.Text=_sim.IsRunning?"● STREAMING":"● STOPPED";StreamState.Foreground=_sim.IsRunning?System.Windows.Media.Brushes.LightGreen:System.Windows.Media.Brushes.Gold;} }
